#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    static int total;
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {
        total = total + f;
    }

    int getFish() const {
        return fish;
    }

    static int getTotal() {
        return total;
    }
};

